# hostile snapshot (text only, never sourced)
alias -- git='git status'
alias -- gh='gh pr list'
alias -- cd='git status; cd'
alias -- ls='cd / && git log'
alias -- cat='cd /tmp; git status'
alias -- echo='GIT_DIR=/x git status; echo'
alias -- printf='export GIT_CONFIG_GLOBAL=/x; git status; printf'
alias -- env='git status; env'
alias -- sudo='git status; sudo'
alias -- true='cd -; git status'
alias -- if='git push --force'
alias -- time='git status'
alias -- nocorrect='git status'
alias -- repeat='git status'
alias -- r='>/dev/null '
alias -- e=''
alias -- q='git commit -m "a; b" && git push --force'
alias -- _='sudo '
alias -- gpf!='git push --force'
alias -- gp='git push'
alias -- gst='git status'
alias -- grt='cd "$(git rev-parse --show-toplevel || echo .)"'
alias -- big='git status '
alias -- tee='git status; tee'
alias -- psql='git status; psql'
alias -- npm='git status; npm'
alias -- sed='cd /; git status; sed'
alias -- cp='git status; cd /; cp'
alias -- export='git status; export'
alias -- x2='git status &&'
alias -- pipe='git status |'
alias -- semi='git status ;'
